# check_mesh.py - read-only check of a BASEmesh .2dm mesh generated by the user from the derived layers.
# Purpose: (1) the mesh is newer than the last change of the derived layers; (2) shortest edges (tiny edges reveal a line vertex
#          very close to a crossing); (3) smallest element angles (< rules.min_angle_deg reported); (4) materials of the mesh vs the
#          mat_id of the region points; (5) nodestrings of the mesh vs the nodestring layer (count and names, when present in the file).
# Inputs : the .2dm file (argument, relative to the working folder, e.g. mesh/quality-mesh.2dm); cfg outputs (derived layers, for dates,
#          mat_id and nodestring names); params.check_mesh.min_edge (edges shorter than this are listed, default 0.01 m),
#          params.check_mesh.list (how many worst items to print, default 10); rules.min_angle_deg.
# Outputs: print only, numbered lines with OK / **CHECK**.
# Run    : cd <working folder>; <geo python> <skill>/scripts/check_mesh.py [-c rcs_config.json] mesh/<file>.2dm
import os, sys, datetime, collections
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import common
import numpy as np

ap = common.parser('check a .2dm mesh against the derived layers'); ap.add_argument('mesh')
args = ap.parse_args(); cfg = common.load(args)
P = cfg.get('params', {}).get('check_mesh', {}); MIN_EDGE = P.get('min_edge', 0.01); NLIST = P.get('list', 10)
MIN_ANG = cfg['rules'].get('min_angle_deg', 30.0)
k = 0
def out(msg, ok=None):
    global k; k += 1; print(f'{k}. {msg}' + ('' if ok is None else ('  OK' if ok else '  **CHECK**')))

# ---- read the .2dm: ND id x y z ; E3T id n1 n2 n3 mat ; E4Q id n1..n4 mat ; NS n1 n2 ... -nlast [name]
nodes = {}; tri = []; quad = []; ns = []; cur = []
with open(args.mesh) as f:
    for line in f:
        t = line.split()
        if not t: continue
        if t[0] == 'ND': nodes[int(t[1])] = (float(t[2]), float(t[3]))
        elif t[0] == 'E3T': tri.append([int(v) for v in t[1:6]])
        elif t[0] == 'E4Q': quad.append([int(v) for v in t[1:7]])
        elif t[0] == 'NS':
            # a nodestring may span several NS lines; a negative node id closes it, an optional name may follow
            for v in t[1:]:
                try:
                    n = int(v)
                except ValueError:
                    if ns and ns[-1][1] is None: ns[-1] = (ns[-1][0], v)
                    continue
                cur.append(abs(n))
                if n < 0: ns.append((cur, None)); cur = []
ids = np.array(sorted(nodes)); XY = np.array([nodes[i] for i in ids]); pos = {i: j for j, i in enumerate(ids)}
out(f'mesh {args.mesh}: {len(nodes)} nodes, {len(tri)} triangles, {len(quad)} quadrilaterals, {len(ns)} nodestrings')

# ---- 1. dates
mt = datetime.datetime.fromtimestamp(os.path.getmtime(args.mesh))
lay = {key: datetime.datetime.fromtimestamp(os.path.getmtime(cfg.layer('out', key))) for key in ('breaklines', 'boundary', 'regions')}
newest = max(lay.values())
out(f'mesh written {mt:%Y-%m-%d %H:%M:%S}; last change of breaklines/boundary/regions {newest:%Y-%m-%d %H:%M:%S}'
    + ('' if mt >= newest else ' -> the mesh is OLDER than the layers: regenerate it'), mt >= newest)

# ---- elements as node-index arrays (quads split into their 4 edges / 4 angles)
def polys():
    for e in tri: yield [pos[n] for n in e[1:4]], e[4]
    for e in quad: yield [pos[n] for n in e[1:5]], e[5]
mats = collections.Counter(); edges = set(); minang = []; nomat = []
for p, m in polys():
    mats[m] += 1; n = len(p)
    if m == 0: nomat.append(XY[p].mean(axis=0))
    for i in range(n):
        a, b = p[i], p[(i + 1) % n]; edges.add((a, b) if a < b else (b, a))
    P3 = XY[p]; angs = []
    for i in range(n):
        u = P3[i - 1] - P3[i]; v = P3[(i + 1) % n] - P3[i]
        c = (u @ v) / (np.hypot(*u) * np.hypot(*v)); angs.append(np.degrees(np.arccos(np.clip(c, -1, 1))))
    minang.append((min(angs), P3.mean(axis=0)))

# ---- 2. shortest edges
E = np.array(sorted(edges)); L = np.hypot(*(XY[E[:, 0]] - XY[E[:, 1]]).T); o = np.argsort(L)
short = [(round(float(L[i]), 4), tuple(round(float(v), 2) for v in XY[E[i, 0]])) for i in o[:NLIST]]
nshort = int((L < MIN_EDGE).sum())
out(f'edges: {len(E)}, shortest {L.min():.4f} m; edges shorter than {MIN_EDGE} m: {nshort}; shortest {NLIST} (length, at): {short}', nshort == 0)

# ---- 3. smallest angles
A = np.array([a for a, _ in minang]); oa = np.argsort(A)
worst = [(round(float(minang[i][0]), 1), tuple(round(float(v), 1) for v in minang[i][1])) for i in oa[:NLIST]]
nacute = int((A < MIN_ANG).sum())
out(f'element angles: smallest {A.min():.1f} deg; elements with an angle < {MIN_ANG} deg: {nacute}; worst {NLIST} (angle, centre): {worst}', None)

# ---- 4. materials vs region points
try:
    import geom
    rg = geom.read(cfg.layer('out', 'regions'))
    fmat = cfg.f('regions', 'mat_id'); fhole = cfg.f('regions', 'hole')
    want = {int(v) for v, h in zip(rg[fmat], rg[fhole]) if v == v and not (h == h and h)}
    got = set(mats)
    out(f'materials in the mesh {sorted(got)} (elements per material {dict(sorted(mats.items()))}); mat_id of the region points (holes excluded) {sorted(want)}; '
        f'missing in the mesh {sorted(want - got)}, unexpected {sorted(got - want)}', got == want)
    if nomat:
        c = np.array(nomat)
        out(f'elements with material 0 (a face without region point): {len(c)}, centre {tuple(round(float(v), 1) for v in c.mean(axis=0))}, '
            f'extent x {c[:, 0].min():.1f}..{c[:, 0].max():.1f}, y {c[:, 1].min():.1f}..{c[:, 1].max():.1f}', False)
    # ---- 5. nodestrings
    bd = geom.read(cfg.layer('out', 'boundary')); names = set(bd[cfg.f('boundary', 'name')])
    named = [nm for _, nm in ns if nm]
    if named:
        out(f'nodestrings: mesh {len(ns)}, layer {len(names)}; in the layer but not in the mesh {sorted(names - set(named))[:20]}', set(named) == names)
    else:
        out(f'nodestrings: mesh {len(ns)}, layer {len(names)} (names not stored in the .2dm: count only)', len(ns) == len(names))
except ImportError:
    out('materials and nodestrings not checked: geopandas not available in this interpreter (use the geo interpreter)', False)
